rows=[]
for r in range(30):
    row=[0]*30
    if 1 <= r <= 25:
        row[1]=5; row[25]=5
        if r in (1,25):
            for c in range(2,25): row[c]=5
        elif r in (2,24):
            for c in range(2,25): row[c]=2
        elif r in (3,23):
            row[2]=2
            for c in range(3,24): row[c]=5
            row[24]=2
        else:
            row[2]=2; row[3]=5; row[23]=5; row[24]=2
    rows.append(row)
print('\n'.join('['+', '.join(map(str,row))+'],' for row in rows))

seq=[2,5,0,5,2,5,0,5,2,5,0,5]
rows=[]
for r in range(30):
    row=[0]*30
    if 1<=r<=25:
        row[1]=row[25]=5
        if r in (1,25):
            for c in range(2,25): row[c]=5
        else:
            for c in range(2,25):
                d=min(r-2,24-r,c-2,24-c)
                row[c]=seq[d]
    rows.append(row)
assert all(len(x)==30 for x in rows)
print('\n'.join('['+','.join(map(str,x))+'],' for x in rows))
